interface ShapeVisitor {
  visitCircle(c: Circle): string;
  visitSquare(s: Square): string;
}

interface Shape {
  accept(visitor: ShapeVisitor): string;
}

class Circle implements Shape {
  constructor(public radius: number) {}
  accept(visitor: ShapeVisitor) { return visitor.visitCircle(this); }
}
class Square implements Shape {
  constructor(public side: number) {}
  accept(visitor: ShapeVisitor) { return visitor.visitSquare(this); }
}

// A brand-new operation, with zero changes to Circle or Square
class SvgExportVisitor implements ShapeVisitor {
  visitCircle(c: Circle) { return `<circle r="${c.radius}"/>`; }
  visitSquare(s: Square) { return `<rect width="${s.side}"/>`; }
}

shapes.map((shape) => shape.accept(new SvgExportVisitor()));
